def inject_css_with_background(css_path=CSS_FILE, bg_path=BG_FILE):
    """
    Inject CSS into the page and embed background image as base64 data URI.
    This function writes styles for both body::before and Streamlit app container to
    maximize compatibility across Streamlit versions and deployments.
    """
    default_css = r"""
    :root{
      --card-bg: rgba(18,20,22,0.6);
      --card-elev: 0 6px 20px rgba(2,6,23,0.6);
      --accent: #2b8cbe;
      --muted: #98a3ab;
    }

    /* body fallback - blurred background image */
    body::before {
      content: "";
      position: fixed;
      inset: 0;
      z-index: -2;
      background-image: url("{BG_DATA_URI}");
      background-size: cover;
      background-position: center;
      filter: blur(2px) saturate(0.95);
      transform: scale(1.02);
      opacity: 0.65;
    }
    /* dark overlay for readability */
    body::after {
      content: "";
      position: fixed;
      inset: 0;
      z-index: -1;
      background: linear-gradient(180deg, rgba(6,10,13,0.65), rgba(6,10,13,0.65));
    }

    /* also set background on Streamlit app container for compatibility */
    [data-testid="stAppViewContainer"] {
      background-image: url("{BG_DATA_URI}") !important;
      background-size: cover !important;
      background-position: center !important;
      background-repeat: no-repeat !important;
      background-attachment: fixed !important;
    }
    [data-testid="stAppViewContainer"]::before {
      content: "";
      position: absolute;
      inset: 0;
      z-index: -1;
      background: linear-gradient(180deg, rgba(6,10,13,0.45), rgba(6,10,13,0.45));
    }

    .block-container { padding: 1.25rem 2rem; color: #e8eef5; font-family: 'Inter', system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial; }
    .center-header { text-align: center; margin-bottom: 0.6rem; }
    .center-header h1 { font-size: 2.4rem; margin: 0; letter-spacing: -0.5px; }
    .center-header p { color: var(--muted); margin-top: 6px; }
    .card { background: linear-gradient(180deg, rgba(255,255,255,0.02), rgba(255,255,255,0.01)); border-radius: 12px; padding: 18px; box-shadow: var(--card-elev); border: 1px solid rgba(255,255,255,0.03); margin-bottom: 12px; }
    .stButton>button { border-radius: 10px; padding: 8px 14px; background: linear-gradient(180deg, var(--accent), #1f6c95); color: white; border: none; }
    .stTable td, .stTable th, .stDataFrame td, .stDataFrame th { padding: 8px 10px; border-color: rgba(255,255,255,0.04); }
    .small-muted { color: var(--muted); font-size: 0.95rem; }
    @media (max-width: 800px) { .center-header h1 { font-size: 1.8rem; } .block-container { padding: 1rem; } }
    """


    bg_uri = ""
    bg_found = False
    if os.path.exists(bg_path):
        try:
            with open(bg_path, "rb") as f:
                im_bytes = f.read()
            # detect mime
            if bg_path.lower().endswith(".png"):
                mime = "image/png"
            elif bg_path.lower().endswith(".webp"):
                mime = "image/webp"
            else:
                mime = "image/jpeg"
            bg_b64 = base64.b64encode(im_bytes).decode("utf-8")
            bg_uri = f"data:{mime};base64,{bg_b64}"
            bg_found = True
        except Exception as e:
            st.sidebar.warning(f"Could not embed background image: {e}")
            bg_uri = ""
            bg_found = False
    else:
        # file not found
        bg_uri = ""
        bg_found = False

    # Read user-provided CSS if exists; otherwise use default_css
    css_text = default_css
    css_found = False
    if os.path.exists(css_path):
        try:
            with open(css_path, "r", encoding="utf-8") as f:
                css_text = f.read()
            css_found = True
        except Exception as e:
            st.sidebar.warning(f"Failed to read {css_path}. Using built-in styles. Error: {e}")
            css_found = False

    # Replace placeholder
    css_text = css_text.replace("{BG_DATA_URI}", bg_uri)

    # Inject CSS
    st.markdown(f"<style>{css_text}</style>", unsafe_allow_html=True)

    # Provide debug info in sidebar
    st.sidebar.markdown("### Theme / assets")
    st.sidebar.write(f"styles.css present: {'Yes' if css_found else 'No'}")
    st.sidebar.write(f"{bg_path} present: {'Yes' if bg_found else 'No'}")
    if not bg_found:
        st.sidebar.info("To show background place an image named 'background.png' (or change BG_FILE) in the app folder and restart the app.")

def load_artifacts():
    pipeline_path = None
    for p in PIPELINE_FILES:
        if os.path.exists(p):
            pipeline_path = p
            break
    if pipeline_path is None:
        raise FileNotFoundError("Pipeline file not found.")

    encoder_path = None
    for e in ENCODER_FILES:
        if os.path.exists(e):
            encoder_path = e
            break
    if encoder_path is None:
        raise FileNotFoundError("Label encoder not found.")

    pipe = joblib.load(pipeline_path)
    le = joblib.load(encoder_path)
    return pipe, le, pipeline_path, encoder_path

def infer_expected_columns(pipe):
    try:
        pre = pipe.named_steps.get("preprocessor", None)
        if pre is not None:
            cont = list(pre.transformers_[0][2])
            passthrough = list(pre.transformers_[1][2])
            return cont + passthrough
    except:
        pass

    if hasattr(pipe, "feature_names_in_"):
        return list(pipe.feature_names_in_)

    return None

def safe_predict(pipe, le, df):
    try:
        preds = pipe.predict(df)
        probs = pipe.predict_proba(df) if hasattr(pipe, "predict_proba") else None
    except:
        # attempt to reindex using pipeline feature names and retry
        if hasattr(pipe, "feature_names_in_"):
            df = df.reindex(columns=pipe.feature_names_in_, fill_value=0)
            preds = pipe.predict(df)
            probs = pipe.predict_proba(df) if hasattr(pipe, "predict_proba") else None
        else:
            raise

    return preds, le.inverse_transform(preds), probs

def select_all_cb():
    # set the multiselect state to all symptoms (allowed inside callback)
    st.session_state["multi_symp"] = symptom_cols.copy()
    # ensure checkboxes reflect the selection (they will be created with these keys)
    for s in symptom_cols:
        st.session_state[f"chk_{s}"] = True

def clear_all_cb():
    st.session_state["multi_symp"] = []
    for s in symptom_cols:
        st.session_state[f"chk_{s}"] = False

def checkbox_changed(symptom):
    """Called when any symptom checkbox changes. Update multiselect state accordingly."""
    ms = list(st.session_state.get("multi_symp", []))  # current multiselect list
    chk_key = f"chk_{symptom}"
    checked = bool(st.session_state.get(chk_key, False))
    if checked and (symptom not in ms):
        ms.append(symptom)
    if (not checked) and (symptom in ms):
        ms.remove(symptom)
    st.session_state["multi_symp"] = ms

/* ======================= styles.css — Ultra Premium Medical UI =======================
   - Glassmorphism cards
   - Soft gradients & accents
   - Smooth animations, hover lifts
   - Refined typography (Poppins / Inter)
   - Improved inputs, buttons, tables, sidebar
   ===================================================================================*/

/* ---------- Theme tokens ---------- */
:root{
  --bg-dark: #071428;            /* deep background tint */
  --panel-glass: rgba(255,255,255,0.04);
  --panel-border: rgba(255,255,255,0.06);
  --muted: #b9c7d1;
  --text: #eaf6fb;
  --accent-1: #20c0ff;          /* bright cyan */
  --accent-2: #1272b8;          /* darker blue */
  --accent-3: #7af0ff;          /* highlight */
  --glass-strong: rgba(255,255,255,0.06);
  --glass-weak: rgba(255,255,255,0.02);
  --shadow-1: 0 8px 30px rgba(2,12,25,0.55);
  --radius-lg: 14px;
  --radius-md: 10px;
}

/* ---------- Background + overlay (BG_DATA_URI replaced by app) ---------- */
body::before{
  content:"";
  position: fixed;
  inset: 0;
  z-index: -3;
  background-image: url("{BG_DATA_URI}");
  background-size: cover;
  background-position: center;
  filter: blur(1px) brightness(1.05) saturate(1.05);
  transform: scale(1.01);
  opacity: 0.92;
}
body::after{
  content:"";
  position: fixed;
  inset: 0;
  z-index: -2;
  background: linear-gradient(180deg, rgba(6,12,20,0.26), rgba(3,10,18,0.64));
}

/* Also set the Streamlit container (compatibility) */
[data-testid="stAppViewContainer"]{
  background-image: url("{BG_DATA_URI}") !important;
  background-size: cover !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  background-attachment: fixed !important;
}

/* ---------- Base layout ---------- */
.block-container{
  padding: 1.5rem 2.2rem;
  color: var(--text);
  font-family: 'Poppins', 'Inter', system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial;
  -webkit-font-smoothing: antialiased;
}

/* ---------- Header ---------- */
.center-header { text-align: center; margin-bottom: 0.6rem; }
.center-header h1 {
  font-size: 2.8rem;
  margin: 0;
  color: #ffffff;
  font-weight: 700;
  letter-spacing: -0.6px;
  text-shadow: 0 6px 22px rgba(0,0,0,0.55);
}
.center-header p {
  color: var(--muted);
  margin-top: 6px;
  font-size: 1.02rem;
}

/* ---------- Sidebar (styled) ---------- */

[data-testid="stSidebar"]{
  background: linear-gradient(180deg, rgba(6,12,20,0.55), rgba(3,10,18,0.7));
  border-right: 1px solid rgba(255,255,255,0.03);
}
[data-testid="stSidebar"] .css-1lcbmhc { padding: 1rem 1rem; } /* small variant containers */

/* ---------- Card / Panel (glassmorphism) ---------- */
.card {
  background: linear-gradient(180deg, rgba(255,255,255,0.03), rgba(255,255,255,0.015));
  border: 1px solid var(--panel-border);
  border-radius: var(--radius-lg);
  padding: 18px;
  box-shadow: var(--shadow-1);
  backdrop-filter: blur(8px) saturate(1.08);
  transition: transform .18s ease, box-shadow .18s ease;
}
.card:hover{
  transform: translateY(-6px);
  box-shadow: 0 18px 60px rgba(2,12,30,0.6);
}

/* smaller compact card */
.card-sm { padding: 12px; border-radius: var(--radius-md); }

/* ---------- Buttons (pill + gradient + subtle hover) ---------- */
.stButton>button{
  background: linear-gradient(180deg, var(--accent-1), var(--accent-2));
  color: white;
  font-weight: 600;
  border: none;
  border-radius: 12px;
  padding: 10px 18px;
  box-shadow: 0 8px 28px rgba(18,128,200,0.18);
  transition: transform .14s ease, box-shadow .14s ease;
}
.stButton>button:hover{
  transform: translateY(-3px);
  box-shadow: 0 14px 36px rgba(18,128,200,0.26);
}

/* small ghost button style (for secondary actions) */
.btn-ghost{
  background: transparent !important;
  border: 1px solid rgba(255,255,255,0.06) !important;
  color: var(--text) !important;
}

/* ---------- Input fields / selects ---------- */
/* Use dark translucent backgrounds for inputs for contrast */
div[role="listbox"], .stSelectbox > div > div, .stMultiSelect > div, .stTextInput > div, .stNumberInput > div {
  background: rgba(0,0,0,0.45) !important;
  border-radius: 10px !important;
  border: 1px solid rgba(255,255,255,0.04) !important;
  color: var(--text) !important;
  padding: 6px 10px !important;
}

/* placeholder / muted text */
input::placeholder, .stSelectbox label, .stNumberInput label {
  color: var(--muted) !important;
}

/* increment buttons (number inputs) */
.stNumberInput button { background: var(--accent-2) !important; color: #fff !important; }

/* ---------- Table styling ---------- */
.stDataFrame table{
  background: rgba(255,255,255,0.02);
  border-radius: 10px;
  overflow: hidden;
}
.stDataFrame thead th{
  background: linear-gradient(180deg, rgba(255,255,255,0.03), rgba(255,255,255,0.01));
  color: var(--text);
  font-weight: 700;
}
.stDataFrame tbody td{
  color: var(--text);
  padding: 10px 12px;
  border-bottom: 1px solid rgba(255,255,255,0.02);

}

/* ---------- Charts container ---------- */
.plotly-graph-div, .stPlotlyChart {
  border-radius: 10px;
  padding: 6px;
}

/* ---------- Tiny helpers ---------- */
.small-muted { color: var(--muted); font-size: 0.95rem; }
.kpi {
  background: linear-gradient(180deg, rgba(255,255,255,0.02), rgba(255,255,255,0.01));
  padding: 12px;
  border-radius: 10px;
  border: 1px solid rgba(255,255,255,0.03);
  text-align: center;
}

/* ---------- Responsive tweaks ---------- */
@media (max-width: 980px){
  .center-header h1 { font-size: 1.9rem; }
  .block-container { padding: 1rem; }
  .card { padding: 12px; }
}

/* ---------- Micro animations ---------- */
@keyframes floatIn {
  from { transform: translateY(6px); opacity: 0; }
  to   { transform: translateY(0); opacity: 1; }
}
.card { animation: floatIn .28s ease both; }

/* =========================
   ADDITIONS / FIXES (safe)
   - fix label wrapping & sidebar selectbox clipping
   - better spacing for labels & number inputs
   ========================= */

/* Ensure selectbox labels stack and wrap so they never get cut */
.stSelectbox label,
.stMultiSelect label,
.stTextInput label,
.stNumberInput label {
  display: block !important;
  white-space: normal !important;
  line-height: 1.15 !important;
  margin-bottom: 0.35rem !important;
}

/* Make the selectbox container allow overflow and have comfortable min width
   This prevents the text from being truncated inside narrow streamlit containers */
.stSelectbox, .stMultiSelect {
  min-width: 220px !important;
  overflow: visible !important;
}

/* Streamlit sometimes wraps the dropdown in an inline flex; ensure the inner token area grows */
.stMultiSelect > div, .stSelectbox > div {
  min-height: 42px !important;
  align-items: center !important;
}

/* Slightly reduce the padding on the number inputs so the +/- buttons do not push label */
.stNumberInput > div {
  padding: 6px 8px !important;
}

/* Give number input value a stable width so long values don't push controls off-screen */
.stNumberInput input[type="number"] {
  min-width: 90px !important;
}

/* Make sidebar controls flow nicely (avoid clipping in narrow sidebar) */
[data-testid="stSidebar"] .stSelectbox,
[data-testid="stSidebar"] .stNumberInput,
[data-testid="stSidebar"] .stMultiSelect {
  min-width: 100% !important;
  box-sizing: border-box !important;
}

/* Small visual: add subtle left padding on labels inside sidebar */
[data-testid="stSidebar"] label {
  padding-left: 2px;
}

/* If the dropdown token area shows a long token, allow it to wrap to multiple lines */
.stMultiSelect .css-1qi6w8s { /* streamlit internal — safe to include as fallback */
  white-space: normal !important;
}

/* Final safety: force full width for block-container child elements to avoid accidental overflow */
.block-container > div {
  width: 100% !important;
  box-sizing: border-box !important;
}

/* ============================================
   FINAL FIX FOR CROPPED LABELS (Selectbox/Number)
   Forces labels to auto-expand height
   ============================================ */

/* Ensure Streamlit's label wrapper grows to fit text */
.stSelectbox label,
.stNumberInput label,
.stMultiSelect label,
.stTextInput label {
    height: auto !important;
    white-space: normal !important;
    line-height: 1.3 !important;
    overflow: visible !important;
    display: block !important;
}

/* Override Streamlit's internal container height */
.css-175i5b5,                    /* generic label class */
.css-1p3v1b5,                    /* selectbox internal wrapper */
.css-1n76uvr,                    /* label wrapper in recent Streamlit */
.css-1uorj75,                    /* number input label wrapper */
.css-1j4d9dg                     /* fallback for multi-select label */
{
    height: auto !important;
    min-height: 24px !important;
    overflow: visible !important;
    display: block !important;
    white-space: normal !important;
}

/* Ensure parent container doesn’t clip the label */
.stSelectbox, .stNumberInput, .stMultiSelect {
    overflow: visible !important;
}
